begin;
with j as (select * from jsonb_to_recordset($law7d0003$[{"code_id":"APK_RF","article_number":"135","version_date":"2002-07-24","article_text":"1. При подготовке дела к судебному разбирательству судья:\n\n1) вызывает стороны и (или) их представителей и проводит с ними собеседование в целях выяснения обстоятельств, касающихся существа заявленных требований и возражений; предлагает раскрыть доказательства, их подтверждающие, и представить при необходимости дополнительные доказательства в определенный срок; разъясняет сторонам их права и обязанности, последствия совершения или несовершения процессуальных действий в установленный срок; определяет по согласованию со сторонами сроки представления необходимых доказательств и проведения предварительного судебного заседания;\n\n2) разъясняет сторонам их право на рассмотрение дела с участием арбитражных заседателей, право передать спор на разрешение третейского суда, право обратиться на любой стадии арбитражного процесса в целях урегулирования спора за содействием к посреднику, в том числе медиатору, судебному примирителю, использовать другие примирительные процедуры, разъясняет условия и порядок реализации данного права, существо и преимущества примирительных процедур, а также последствия совершения таких действий, принимает меры для заключения сторонами мирового соглашения, содействует примирению сторон; (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n3) оказывает содействие сторонам в получении необходимых доказательств, истребует по ходатайству сторон, а в случаях, предусмотренных настоящим Кодексом, по своей инициативе необходимые доказательства, разрешает вопросы о назначении экспертизы, вызове в судебное заседание экспертов, свидетелей, привлечении переводчика, специалиста, необходимости осмотра на месте письменных и вещественных доказательств, а также принимает иные меры для представления сторонами доказательств; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n4) по ходатайству сторон разрешает вопросы об обеспечении иска, о предоставлении встречного обеспечения, а также об обеспечении доказательств, направляет судебные поручения;\n\n5) рассматривает вопросы о вступлении в дело других лиц, замене ненадлежащего ответчика, соединении и разъединении нескольких требований, принятии встречного иска, возможности проведения выездного судебного заседания;\n\n6) совершает иные направленные на обеспечение правильного и своевременного рассмотрения дела действия.\n\n2. Действия по подготовке дела к судебному разбирательству совершаются судьей в порядке, предусмотренном настоящим Кодексом.\n\n3. Суд выносит определение о переходе к рассмотрению дела в порядке упрощенного производства в случае, если при подготовке к судебному разбирательству дела истцом заявлено ходатайство о рассмотрении дела в порядке упрощенного производства и в арбитражный суд представлено согласие ответчика на рассмотрение дела в порядке упрощенного производства или суд по своей инициативе предлагает рассмотреть дело в порядке упрощенного производства и при согласии сторон выносит соответствующее определение.\n\nОдновременно с указанным определением сторонам направляются данные, необходимые для идентификации сторон, в целях доступа к материалам дела в электронном виде.\n\nИсковое заявление, заявление по данному делу размещаются в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа не позднее следующего дня после дня вынесения указанного определения. (В редакции федеральных законов от 23.06.2016 № 220-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n(Дополнение частью - Федеральный закон от 25.06.2012 № 86-ФЗ)","article_title":"Статья 135. Действия по подготовке дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613cc6477db77fe4cabaff1a6785f6d037f869ccebd36a0c6c6be51ded199f20"},{"code_id":"APK_RF","article_number":"136","version_date":"2002-07-24","article_text":"При неявке в предварительное судебное заседание надлежащим образом извещенных истца и (или) ответчика, других заинтересованных лиц, которые могут быть привлечены к участию в деле, заседание проводится в их отсутствие.\n\n1) разрешает ходатайства сторон;\n\n2) определяет достаточность представленных доказательств, доводит до сведения сторон, какие доказательства имеются в деле;\n\n21) выясняет мнение сторон о возможности урегулировать спор, предлагает сторонам использовать примирительные процедуры; при выявлении намерения сторон обратиться к судебному примирителю суд утверждает его кандидатуру, выбранную сторонами, в порядке, установленном настоящим Кодексом; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n3) выносит на рассмотрение вопросы, разрешаемые при подготовке дела к судебному разбирательству, и совершает предусмотренные настоящим Кодексом иные процессуальные действия.\n\nтву лиц, участвующих в деле, вправе объявить перерыв в предварительном судебном заседании на срок не более пяти дней для представления ими дополнительных доказательств.","article_title":"Статья 136. Предварительное судебное заседание","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86c67f0cdfa63c53fd89949527cd9ff21087b9c1441d09575986903e5937a5b9"},{"code_id":"APK_RF","article_number":"137","version_date":"2002-07-24","article_text":"1. Судья, признав дело подготовленным, выносит определение о назначении дела к судебному разбирательству.\n\n2. В определении о назначении дела к судебному разбирательству указывается на окончание подготовки дела к судебному разбирательству и разрешение вопросов о привлечении к делу третьих лиц, принятие встречного иска, соединение или разъединение нескольких требований, привлечение арбитражных заседателей, а также на разрешение других вопросов, если по ним не были вынесены соответствующие определения, время и место проведения судебного заседания в арбитражном суде первой инстанции.\n\n3. Копии определения о назначении дела к судебному разбирательству направляются лицам, участвующим в деле.","article_title":"Статья 137. Назначение дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4868312f81d6ca81ba370f34bf352e721e105558da57a798eba4f72144d0a4d8"},{"code_id":"APK_RF","article_number":"138","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает меры для примирения сторон, содействует им в урегулировании спора, руководствуясь при этом интересами сторон и задачами судопроизводства в арбитражных судах.\n\n2. Примирение сторон осуществляется на основе принципов добровольности, сотрудничества, равноправия и конфиденциальности.\n\n3. Стороны пользуются равными правами на выбор примирительной процедуры, определение условий ее проведения, а также кандидатуры посредника, в том числе медиатора, судебного примирителя. По указанным вопросам сторонами может быть заключено соглашение.\n\n4. Примирение сторон возможно на любой стадии арбитражного процесса и при исполнении судебного акта, если иное не предусмотрено настоящим Кодексом и иным федеральным законом.\n\n(Статья в редакции Федерального закона от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138. Примирение сторон","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fea06e5c40001d6908762c3727897fd744ce509c3ec83bf0dd17fa645779722"},{"code_id":"APK_RF","article_number":"138.1","version_date":"2002-07-24","article_text":"1. Примирительная процедура может быть проведена по ходатайству сторон (стороны) либо по предложению арбитражного суда.\n\nПредложение арбитражного суда провести примирительную процедуру может содержаться в определении о принятии искового заявления (заявления) к производству, о подготовке дела к судебному разбирательству или в ином определении по делу, а также может быть сделано судом в устной форме.\n\nДля рассмотрения сторонами вопроса о возможности использовать примирительную процедуру арбитражный суд может объявить перерыв в судебном заседании.\n\n2. В случае согласия сторон с предложением арбитражного суда о проведении примирительной процедуры, удовлетворения ходатайства о проведении примирительной процедуры сторон или одной стороны при согласии другой стороны, а также в случае, предусмотренном частью 2 статьи 190 настоящего Кодекса, арбитражный суд выносит определение о проведении примирительной процедуры и при необходимости об отложении судебного разбирательства.\n\nВ определении о проведении примирительной процедуры арбитражный суд указывает наименования сторон, предмет спора и круг вопросов, для урегулирования которых может быть использована примирительная процедура, сроки проведения примирительной процедуры.\n\nВ определении о проведении примирительной процедуры могут содержаться и иные указания, необходимые для обеспечения надлежащего проведения примирительной процедуры.\n\n3. Примирительная процедура должна быть завершена в срок, установленный судом в определении о проведении примирительной процедуры. По ходатайству сторон указанный срок может быть продлен арбитражным судом.\n\n4. В ходе использования примирительной процедуры стороны могут достичь результатов примирения, установленных настоящим Кодексом.\n\n5. В случае, если стороны не достигли примирения, отказались от проведения примирительных процедур либо истек срок их проведения, арбитражный суд возобновляет судебное разбирательство в порядке, установленном частью 10 статьи 158 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.1. Порядок и сроки проведения примирительной процедуры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc93519f423b0c4bfcee5db223225fb69840c8ce1d0f22fca3502e514857a150"},{"code_id":"APK_RF","article_number":"138.2","version_date":"2002-07-24","article_text":"Споры могут быть урегулированы путем проведения переговоров, посредничества, в том числе медиации, судебного примирения, или использования других примирительных процедур, если это не противоречит федеральному закону.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.2. Виды примирительных процедур","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2201b23ada1bc7be5e2490803dc8f362588f51dd106d0e4c37b126e948e1411"},{"code_id":"APK_RF","article_number":"138.3","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем проведения переговоров в целях примирения.\n\n2. Переговоры осуществляются на условиях, определяемых сторонами.\n\n3. В случаях, предусмотренных федеральным законом или договором, переговоры проводятся в обязательном порядке.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.3. Переговоры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff16d0e662b6a9f4dab114530ddaf94c1f6c6974d16d83af660378b543c35a77"},{"code_id":"APK_RF","article_number":"138.4","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем применения процедуры медиации в порядке, установленном настоящим Кодексом и федеральным законом.\n\n2. В случае заявления сторонами соответствующего ходатайства арбитражный суд откладывает судебное разбирательство на основании части 2 статьи 158 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.4. Медиация","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82f979e6de7cf96e19ba1e8a96f75e08a8c320b5057b7f1fcd32e695b2437ffa"},{"code_id":"APK_RF","article_number":"138.5","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем использования примирительной процедуры с участием судебного примирителя (судебное примирение).\n\n2. Судебное примирение осуществляется на основе принципов независимости, беспристрастности и добросовестности судебного примирителя.\n\nПорядок проведения судебного примирения и требования к судебному примирителю определяются настоящим Кодексом и Регламентом проведения судебного примирения, утверждаемым Верховным Судом Российской Федерации.\n\n3. Судебным примирителем является судья в отставке. Список судебных примирителей формируется и утверждается Пленумом Верховного Суда Российской Федерации на основе предложений арбитражных судов о кандидатурах судебных примирителей из числа судей в отставке, изъявивших желание выступать в качестве судебного примирителя.\n\nСудебный примиритель участвует в процедуре судебного примирения с учетом положений настоящего Кодекса и законодательства о статусе судей в Российской Федерации.\n\n4. Кандидатура судебного примирителя определяется по взаимному согласию сторон из списка судебных примирителей и утверждается определением суда.\n\n5. В целях соотнесения и сближения позиций сторон по делу и выявления дополнительных возможностей для урегулирования спора с учетом интересов сторон, оказания им содействия в достижении взаимоприемлемого результата примирения, основанного также на понимании и оценке сторонами обоснованности заявленных требований и возражений, судебный примиритель вправе вести переговоры со сторонами, другими лицами, участвующими в деле, изучать представленные сторонами документы, знакомиться с материалами дела с согласия арбитражного суда и осуществлять другие действия, необходимые для эффективного урегулирования спора и предусмотренные Регламентом проведения судебного примирения, в том числе давать сторонам рекомендации в целях скорейшего урегулирования спора и сохранения между сторонами деловых отношений.\n\nСудебный примиритель не является участником судебного разбирательства и не вправе совершать действия, влекущие за собой возникновение, изменение либо прекращение прав или обязанностей лиц, участвующих в деле, и других участников арбитражного процесса.\n\nСудья вправе запросить информацию о ходе примирительной процедуры не чаще чем один раз в четырнадцать календарных дней.\n\n6. Порядок и условия оплаты труда судей, пребывающих в отставке и осуществляющих функции судебных примирителей, определяются Правительством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.5. Судебное примирение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1469b3e0e6089e4781155e7d7b385f36b28ab0525c8683976547c20026c90099"},{"code_id":"APK_RF","article_number":"138.6","version_date":"2002-07-24","article_text":"1. Результатами примирения лиц, участвующих в деле, могут быть, в частности:\n\n1) мировое соглашение в отношении всех или части заявленных требований;\n\n2) частичный или полный отказ от иска;\n\n3) частичное или полное признание иска;\n\n4) полный или частичный отказ от апелляционной, кассационной жалобы, надзорной жалобы (представления);\n\n5) признание обстоятельств, на которых другая сторона основывает свои требования или возражения;\n\n6) соглашение по обстоятельствам дела;\n\n7) подписание письма-согласия на государственную регистрацию товарного знака.\n\n2. Признание обстоятельств, признание иска (требований), отказ от иска (требований) полностью или в части принимаются арбитражным судом в порядке, установленном настоящим Кодексом.\n\n3. Признание обстоятельств, на которых другая сторона основывает свои требования или возражения, может быть осуществлено в форме одностороннего заявления о согласии с позицией другой стороны или в форме соглашения по обстоятельствам дела.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.6. Результаты примирительных процедур","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e83456382b23fb39526728e806741446245ba489096c5fec5a241ca39761c6d0"},{"code_id":"APK_RF","article_number":"14","version_date":"2002-07-24","article_text":"1. При применении норм иностранного права арбитражный суд устанавливает содержание этих норм в соответствии с их официальным толкованием, практикой применения и доктриной в соответствующем иностранном государстве.\n\n2. В целях установления содержания норм иностранного права суд может обратиться в установленном порядке за содействием и разъяснением в Министерство юстиции Российской Федерации и иные компетентные органы или организации Российской Федерации и за границей либо привлечь экспертов.\n\nЛица, участвующие в деле, могут представлять документы, подтверждающие содержание норм иностранного права, на которые они ссылаются в обоснование своих требований или возражений, и иным образом содействовать суду в установлении содержания этих норм.\n\nПо требованиям, связанным с осуществлением сторонами предпринимательской и иной экономической деятельности, обязанность доказывания содержания норм иностранного права может быть возложена судом на стороны.\n\n3. Если содержание норм иностранного права, несмотря на принятые в соответствии с настоящей статьей меры, в разумные сроки не установлено, арбитражный суд применяет соответствующие нормы российского права.","article_title":"Статья 14. Применение норм иностранного права","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ab390e3c296616410f88591dd711f00f3ea6fc5051f9f1c2dab68b12fed3641"},{"code_id":"APK_RF","article_number":"140","version_date":"2002-07-24","article_text":"1. Мировое соглашение заключается в письменной форме и подписывается сторонами или их представителями при наличии у них полномочий на заключение мирового соглашения, специально предусмотренных в доверенности или ином документе, подтверждающих полномочия представителя.\n\n2. Мировое соглашение должно содержать согласованные сторонами сведения об условиях, о размере и о сроках исполнения обязательств друг перед другом или одной стороной перед другой.\n\nВ мировом соглашении могут содержаться условия об отсрочке или о рассрочке исполнения обязательств ответчиком, об уступке прав требования, о полном или частичном прощении либо признании долга, о распределении судебных расходов, санкции за его неисполнение или ненадлежащее исполнение и иные условия, не противоречащие федеральному закону. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n3. Если в мировом соглашении отсутствует условие о распределении судебных расходов, арбитражный суд разрешает этот вопрос при утверждении мирового соглашения в общем порядке, установленном настоящим Кодексом.\n\n4. Мировое соглашение составляется и подписывается в количестве экземпляров, превышающем на один экземпляр количество лиц, заключивших мировое соглашение; один из этих экземпляров приобщается арбитражным судом, утвердившим мировое соглашение, к материалам дела.","article_title":"Статья 140. Форма и содержание мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e26a6a3a48f114f89ceaf15275b410814d9656bf930ebb6218dc05e51d35aef9"},{"code_id":"APK_RF","article_number":"141","version_date":"2002-07-24","article_text":"1. Мировое соглашение утверждается арбитражным судом, в производстве которого находится дело. В случае, если мировое соглашение заключено в процессе исполнения судебного акта, оно представляется на утверждение арбитражного суда первой инстанции по месту исполнения судебного акта или в арбитражный суд, принявший указанный судебный акт.\n\n2. Вопрос об утверждении мирового соглашения рассматривается арбитражным судом в судебном заседании. Лица, участвующие в деле, извещаются о времени и месте судебного заседания.\n\n3. В случае неявки в судебное заседание лиц, заключивших мировое соглашение и извещенных надлежащим образом о времени и месте судебного заседания, вопрос об утверждении мирового соглашения не рассматривается арбитражным судом, если от этих лиц не поступило заявление о рассмотрении данного вопроса в их отсутствие.\n\nПри рассмотрении вопроса об утверждении мирового соглашения в случае обжалования судебного акта или его исполнения законность и обоснованность соответствующего судебного акта не проверяются.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\nПри рассмотрении вопроса об утверждении мирового соглашения арбитражный суд вправе предложить сторонам исключить из мирового соглашения отдельные условия, противоречащие закону или нарушающие права и законные интересы других лиц.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n1) утверждение мирового соглашения или отказ в утверждении мирового соглашения;\n\n2) условия мирового соглашения;\n\n3) возвращение истцу из федерального бюджета части уплаченной им государственной пошлины в размерах, установленных федеральными законами о налогах и сборах;\n\n4) распределение судебных расходов.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\nУтверждение мирового соглашения в судах апелляционной, кассационной и надзорной инстанций по предмету заявленных требований влечет за собой отмену судебного акта и прекращение производства по делу.\n\nУтверждение мирового соглашения, заключенного в процессе исполнения судебного акта, влечет за собой прекращение исполнения этого судебного акта при оставлении его в силе. На это указывается в определении суда.\n\nУтверждение мирового соглашения, заключенного при рассмотрении заявления о распределении судебных расходов, понесенных в судах первой, апелляционной, кассационной и надзорной инстанций, влечет за собой прекращение производства по заявлению о распределении судебных расходов.\n\n(Дополнение частью - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 141. Утверждение арбитражным судом мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43390ec411e8b7309dc544af9b20dfa748fc52e90f5ac821af11ab8a4482a639"},{"code_id":"APK_RF","article_number":"142","version_date":"2002-07-24","article_text":"1. Мировое соглашение исполняется лицами, его заключившими, добровольно в порядке и в сроки, которые предусмотрены этим соглашением.\n\n2. Мировое соглашение, не исполненное добровольно, подлежит принудительному исполнению по правилам раздела VII настоящего Кодекса на основании исполнительного листа, выдаваемого арбитражным судом по ходатайству лица, заключившего мировое соглашение.","article_title":"Статья 142. Исполнение мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43c1c144f8981ef5de080f41069bb91f5cfb2e701d16c27515fafea82c5c78fa"},{"code_id":"APK_RF","article_number":"143","version_date":"2002-07-24","article_text":"1. Арбитражный суд обязан приостановить производство по делу в случае:\n\n1) невозможности рассмотрения данного дела до разрешения другого дела, рассматриваемого Конституционным Судом Российской Федерации, Верховным Судом Российской Федерации, судом общей юрисдикции, арбитражным судом; (В редакции  федеральных законов от 14.07.2022 № 337-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n2) участия гражданина, являющегося стороной в деле, в боевых действиях в составе Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, созданных в соответствии с законодательством Российской Федерации, в проведении контртеррористической операции, призыва его на военную службу по мобилизации, заключения им контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, выполнения им задач в условиях чрезвычайного или военного положения, вооруженного конфликта, если такой гражданин не заявил ходатайство о рассмотрении дела в его отсутствие; (В редакции  федеральных законов от 29.12.2022 № 603-ФЗ, от 25.12.2023 № 639-ФЗ)\n\n3) смерти гражданина, являющегося стороной в деле или третьим лицом, заявляющим самостоятельные требования относительно предмета спора, если спорное правоотношение допускает правопреемство; (В редакции Федерального закона от 22.04.2013 № 61-ФЗ)\n\n4) утраты гражданином, являющимся стороной в деле, дееспособности.\n\n2. Арбитражный суд приостанавливает производство по делу и в иных предусмотренных федеральным законом случаях.","article_title":"Статья 143. Обязанность арбитражного суда приостановить производство по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8637bd3ac1201fc580e2bdb9426fc2fd7b5b409bebc9338177f7e834d94e9380"},{"code_id":"APK_RF","article_number":"144","version_date":"2002-07-24","article_text":"Арбитражный суд вправе приостановить производство по делу в случае:\n\n1) назначения арбитражным судом экспертизы;\n\n2) реорганизации организации, являющейся лицом, участвующим в деле;\n\n3) привлечения гражданина, являющегося лицом, участвующим в деле, для выполнения государственной об\n\nязанности;\n\n4) нахождения гражданина, являющегося лицом, участвующим в деле, в лечебном учреждении или длительной служебной командировке;\n\n5) рассмотрения международным судом, судом иностранного государства другого дела, решение по которому может иметь значение для рассмотрения данного дела;\n\n6) участия гражданина, осуществляющего полномочия единоличного исполнительного органа организации, являющейся лицом, участвующим в деле, в боевых действиях в составе Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, созданных в соответствии с законодательством Российской Федерации, в проведении контртеррористической операции, призыва его на военную службу по мобилизации, заключения им контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, выполнения им задач в условиях чрезвычайного или военного положения, вооруженного конфликта, если рассмотрение дела без участия такого гражданина невозможно и полномочия по управлению указанной организацией не переданы им в порядке, установленном законодательством Российской Федерации. (Дополнение пунктом - Федеральный закон от 29.12.2022 № 603-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 639-ФЗ)","article_title":"Статья 144. Право арбитражного суда приостановить производство по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"029eea7f040aef0c579dc2c366436a6cf4e9083bb9d04db7761101c6904ed846"},{"code_id":"APK_RF","article_number":"145","version_date":"2002-07-24","article_text":"Производство по делу приостанавливается:\n\n1) в случаях, предусмотренных пунктом 1 части 1 статьи 143 и пунктом 5 статьи 144 настоящего Кодекса, до вступления в законную силу судебного акта соответствующего суда;\n\n2) в случаях, предусмотренных пунктом 2 части 1 статьи 143 и пунктами 4 и 6 статьи 144 настоящего Кодекса, до устранения обстоятельств, послуживших основанием для приостановления производства по делу; (В редакции  Федерального закона от 29.12.2022 № 603-ФЗ)\n\n3) в случаях, предусмотренных пунктами 3 и 4 части 1 статьи 143 и пунктом 2 статьи 144 настоящего Кодекса, до определения правопреемника лица, участвующего в деле, или назначения недееспособному лицу представителя;\n\n4) в случае, предусмотренном пунктом 1 статьи 144 настоящего Кодекса, до истечения срока, установленного арбитражным судом.","article_title":"Статья 145. Сроки приостановления производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2637cee6264ddd3e37b7272bae9d8148b1c45db7e7e801fb9f2ed10413063712"},{"code_id":"APK_RF","article_number":"146","version_date":"2002-07-24","article_text":"Арбитражный суд возобновляет производство по делу по заявлению лиц, участвующих в деле, или по своей инициативе после устранения обстоятельств, вызвавших его приостановление, либо до их устранения по заявлению лица, по ходатайству которого производство по делу было приостановлено.","article_title":"Статья 146. Возобновление производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6eeffc526fb3d58fb4062bbf6cd20d9d45666b2db78e1efca3d573c9416802"},{"code_id":"APK_RF","article_number":"147","version_date":"2002-07-24","article_text":"1. О приостановлении производства по делу, его возобновлении или об отказе в возобновлении арбитражный суд выносит определение.\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда о приостановлении производства по делу, об отказе в возобновлении производства по делу может быть обжаловано.","article_title":"Статья 147. Порядок приостановления и возобновления производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ae203152800c60ecd2dc2181a19ae2a503b019a8ed6df9a2c7e41787c7105ba"},{"code_id":"APK_RF","article_number":"148","version_date":"2002-07-24","article_text":"1) в производстве арбитражного суда, суда общей юрисдикции, третейского суда имеется дело по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n2) истцом не соблюден претензионный или иной досудебный порядок урегулирования спора с ответчиком, за исключением случаев, если его соблюдение не предусмотрено федеральным законом; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n3) при рассмотрении заявления об установлении фактов, имеющих юридическое значение, выясняется, что возник спор о праве;\n\n4) заявлено требование, которое в соответствии с федеральным законом должно быть рассмотрено в деле о банкротстве;\n\n5) имеется соглашение сторон о рассмотрении данного спора третейским судом, если любая из сторон не позднее дня представления своего первого заявления по существу спора в арбитражном суде первой инстанции заявит по этому основанию возражение в отношении рассмотрения дела в арбитражном суде, за исключением случаев, если арбитражный суд установит, что это соглашение недействительно, утратило силу или не может быть исполнено;\n\n6) стороны заключили соглашение о передаче спора на разрешение третейского суда во время судебного разбирательства до принятия судебного акта, которым заканчивается рассмотрение дела по существу, если любая из сторон заявит по этому основанию возражение в отношении рассмотрения дела в арбитражном суде, за исключением случаев, если арбитражный суд установит, что это соглашение недействительно, утратило силу или не может быть исполнено;\n\n7) исковое заявление не подписано или подписано лицом, не имеющим права подписывать его, либо лицом, должностное положение которого не указано;\n\n8) заявлено исковое требование о взыскании судебных расходов, которое подлежит рассмотрению в соответствии со статьей 112 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n9) истец повторно не явился в судебное заседание, в том числе по вызову суда, и не заявил ходатайство о рассмотрении дела в его отсутствие или об отложении судебного разбирательства, а ответчик не требует рассмотрения дела по существу. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 148. Основания для оставления искового заявления без рассмотрения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0a4c50495985fb4afd8aa1413be80db9bdb1a5045a5e93fbf7f5555ca9be4de"}]$law7d0003$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
